      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > main.tf <<'EOF'
provider "aws" {
  region = var.region
}

data "aws_caller_identity" "current" {}

locals {
  bucket_name = coalesce(var.bucket_name, "reports-tfstate-${data.aws_caller_identity.current.account_id}-${var.region}")
}

# Holds the Terraform state for the parent configuration. That state contains the
# IAM access key secret in plaintext, so treat the bucket as sensitive.
resource "aws_s3_bucket" "state" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type    = string
  default = "eu-north-1"
}

variable "bucket_name" {
  type        = string
  default     = null
  description = "State bucket name. Defaults to reports-tfstate-<account id>-<region>."
}
EOF
cat > outputs.tf <<'EOF'
output "bucket" {
  value = aws_s3_bucket.state.id
}

output "init_command" {
  value = "terraform init -backend-config=\"bucket=${aws_s3_bucket.state.id}\" -backend-config=\"region=${var.region}\""
}
EOF
cd ..
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }

  # Partial configuration: bucket and region are supplied at init time, see README.
  backend "s3" {
    key          = "reports/terraform.tfstate"
    encrypt      = true
    use_lockfile = true
  }
}
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
EOF
cat > README.md <<'EOF'
# reports

Terraform for the reports bucket and the key the nightly export job uploads with. The job reads
the key from `terraform output`.

State lives in a versioned, encrypted S3 bucket (with S3 native lockfile locking,
`use_lockfile`, so no DynamoDB table is needed). Requires Terraform >= 1.10.

> **The state contains the uploader's IAM secret access key in plaintext.** Only grant
> access to the state bucket to people who are allowed to read that key.

## One-time setup: create the state bucket

`bootstrap/` creates the bucket. Its own state is local (it can't store state in a bucket that
doesn't exist yet); it rarely changes, so one person runs it once.

```sh
cd bootstrap
terraform init
terraform apply
terraform output init_command
```

The bucket defaults to `reports-tfstate-<account id>-<region>`; override with `-var bucket_name=...`.
Keep `bootstrap/terraform.tfstate` safe (it is gitignored); it holds no secrets, and the bucket can
be re-imported if lost.

## Migrating the existing local state (once, by whoever has `terraform.tfstate`)

From the repo root, with the existing `terraform.tfstate` present:

```sh
terraform init -migrate-state \
  -backend-config="bucket=<bucket from bootstrap>" -backend-config="region=eu-north-1"
```

Answer `yes` to copy the state. Then verify `terraform plan` shows no changes, and delete the
local `terraform.tfstate*` files.

## Day-to-day usage

Each engineer needs AWS credentials with `s3:ListBucket` on the bucket and
`s3:GetObject`/`s3:PutObject`/`s3:DeleteObject` on `reports/*` (the lockfile is
`reports/terraform.tfstate.tflock`).

```sh
terraform init \
  -backend-config="bucket=<bucket from bootstrap>" -backend-config="region=eu-north-1"
terraform plan
terraform apply
```

Concurrent runs are blocked by the lock; don't use `-lock=false`. Previous state versions can be
recovered from S3 object versions.
