terraform fmt -recursive && cd bootstrap && terraform init -backend=false >/dev/null 2>&1; terraform validate 2>&1 | tail -5; cd .. && terraform init -backend=false >/dev/null 2>&1; terraform validate 2>&1 | tail -5; git status --short

